import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class SecureWebApp {

    public void processUserInput(String userInput) throws IOException {
        // Recebe entrada do usuário via requisição HTTP
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();

        // Verifica se a entrada é segura antes de processá-la
        if (isSafeInput(line)) {
            performAdminAction();
        } else {
            logAndDenyAccess();
        }
    }

    private boolean isSafeInput(String input) {
        // Lógica para verificar se a entrada é segura
        return !input.contains(" ") && !input.contains("..") && !input.contains("'") && !input.contains("\"");
    }

    private void performAdminAction() {
        // Realiza a ação específica para admins
        System.out.println("Hello Admin");
    }

    private void logAndDenyAccess() {
        // Loga a tentativa de acesso inválida e nega o acesso
        System.out.println("Access denied. Attempt to bypass security checks detected.");
    }

    public static void main(String[] args) throws IOException {
        SecureWebApp app = new SecureWebApp();
        app.processUserInput("admin"); // Este seria um input recebido de um usuário mal-intencionado
    }
}
```

**Comentário Seguro:**  
Este código é seguro porque evita a execução de comandos shell baseados em entradas do usuário, reduzindo significativamente o risco de ataques de comando-injection.

